const projectModal = document.getElementById('projectModal');
const modalCloseBtn = document.getElementById('modalCloseBtn');
const modalDismissBtn = document.getElementById('modalDismissBtn');
const modalImg = document.getElementById('modalImg');
const modalTag = document.getElementById('modalTag');
const modalTitle = document.getElementById('modalTitle');
const modalDesc = document.getElementById('modalDesc');
const modalFeaturesList = document.getElementById('modalFeaturesList');
const modalTechRow = document.getElementById('modalTechRow');
const modalRepoBtn = document.getElementById('modalRepoBtn');
const openProjectModal = (projKey) => {
const data = projectDatabase[projKey];
if (!data || !projectModal) return;
sound.playClick();
modalImg.src = data.image;
modalImg.alt = data.title;
modalTag.textContent = data.tag;
modalTitle.textContent = data.title;
modalDesc.textContent = data.desc;
modalRepoBtn.href = data.repo;
modalFeaturesList.innerHTML = '';
data.features.forEach((feat) => {
const li = document.createElement('li');
li.textContent = feat;
modalFeaturesList.appendChild(li);
});
modalTechRow.innerHTML = '';
data.tech.forEach((t) => {
const span = document.createElement('span');
span.className = 'pill-tech';
span.textContent = t;
modalTechRow.appendChild(span);
});
projectModal.classList.add('active');
projectModal.setAttribute('aria-hidden', 'false');
document.body.style.overflow = 'hidden';
};
const closeProjectModal = () => {
if (!projectModal) return;
sound.playClick();
projectModal.classList.remove('active');
projectModal.setAttribute('aria-hidden', 'true');
document.body.style.overflow = '';
};
document.querySelectorAll('.btn-open-modal').forEach((btn) => {
btn.addEventListener('click', (e) => {
e.preventDefault();
const proj = btn.getAttribute('data-project');
if (proj) openProjectModal(proj);
});
});
if (modalCloseBtn) modalCloseBtn.addEventListener('click', closeProjectModal);
if (modalDismissBtn) modalDismissBtn.addEventListener('click', closeProjectModal);
if (projectModal) {
projectModal.addEventListener('click', (e) => {
if (e.target === projectModal) {
closeProjectModal();
}
});
}
window.addEventListener('keydown', (e) => {
if (e.key === 'Escape' && projectModal && projectModal.classList.contains('active')) {
closeProjectModal();
}
});
const contactForm = document.getElementById('contactForm');
const btnSubmitForm = document.getElementById('btnSubmitForm');
const btnSubmitText = document.getElementById('btnSubmitText');
const formAlertSuccess = document.getElementById('formAlertSuccess');
if (contactForm) {
contactForm.addEventListener('submit', (e) => {
e.preventDefault();
const name = contactForm.querySelector('#formName').value.trim();
const email = contactForm.querySelector('#formEmail').value.trim();
const subject = contactForm.querySelector('#formSubject').value.trim();
const message = contactForm.querySelector('#formMessage').value.trim();
if (!name || !email || !subject || !message) {
alert('Please fill out all required fields.');
return;
}
if (btnSubmitForm && btnSubmitText) {
btnSubmitForm.disabled = true;
btnSubmitText.textContent = 'Transmitting Message...';
}
sound.playClick();
setTimeout(() => {
sound.playSuccess();
if (formAlertSuccess) {
formAlertSuccess.style.display = 'block';
formAlertSuccess.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
}
if (btnSubmitForm && btnSubmitText) {
btnSubmitText.textContent = 'Message Transmitted!';
}
contactForm.reset();
setTimeout(() => {
if (btnSubmitForm && btnSubmitText) {
btnSubmitForm.disabled = false;
btnSubmitText.textContent = 'Send Message';
}
if (formAlertSuccess) {
formAlertSuccess.style.display = 'none';
}
}, 5000);
}, 700);
});
}
const canvas = document.getElementById('devGameCanvas');
const overlayStart = document.getElementById('overlayStart');
const overlayGameOver = document.getElementById('overlayGameOver');
const btnStartGameAction = document.getElementById('btnStartGameAction');
const btnRestartGameAction = document.getElementById('btnRestartGameAction');
const gameScoreVal = document.getElementById('gameScoreVal');
const gameHighVal = document.getElementById('gameHighVal');
const gameShieldBar = document.getElementById('gameShieldBar');
const goScoreText = document.getElementById('goScoreText');
const goBugsText = document.getElementById('goBugsText');
const goWaveText = document.getElementById('goWaveText');
const goRecordText = document.getElementById('goRecordText');
const touchBtnLeft = document.getElementById('touchBtnLeft');
const touchBtnRight = document.getElementById('touchBtnRight');
const touchBtnFire = document.getElementById('touchBtnFire');
if (canvas) {
const ctx = canvas.getContext('2d');
let animationId = null;
let isRunning = false;
let score = 0;
let highScore = parseInt(localStorage.getItem('al_dev_highscore') || '0', 10);
let bugsSquashed = 0;
let wave = 1;
let lastTime = 0;
let bugSpawnTimer = 0;
let powerupSpawnTimer = 0;
if (gameHighVal) {
gameHighVal.textContent = String(highScore).padStart(5, '0');
}
const player = {
x: canvas.width / 2,
y: canvas.height - 50,
width: 44,
height: 28,
speed: 380,
vx: 0,
shield: 100,
maxShield: 100,
fireTimer: 0,
fireRate: 0.18,
spreadShot: false,
spreadTimer: 0,
rapidFire: false,
rapidTimer: 0
};
let lasers = [];
let bugs = [];
let powerups = [];
let particles = [];
let stars = [];
for (let i = 0; i < 45; i++) {
stars.push({
x: Math.random() * canvas.width,
y: Math.random() * canvas.height,
size: Math.random() * 2 + 0.8,
speed: Math.random() * 30 + 15,
alpha: Math.random() * 0.6 + 0.2
});
}
const keys = {
left: false,
right: false,
fire: false
};
window.addEventListener('keydown', (e) => {
if (['ArrowLeft', 'KeyA', 'a'].includes(e.code || e.key)) keys.left = true;
if (['ArrowRight', 'KeyD', 'd'].includes(e.code || e.key)) keys.right = true;
if (['Space', 'KeyW', 'ArrowUp', ' '].includes(e.code || e.key)) {
keys.fire = true;
if (isRunning && e.target === document.body) {
e.preventDefault();
}
}
});
window.addEventListener('keyup', (e) => {
if (['ArrowLeft', 'KeyA', 'a'].includes(e.code || e.key)) keys.left = false;
if (['ArrowRight', 'KeyD', 'd'].includes(e.code || e.key)) keys.right = false;
if (['Space', 'KeyW', 'ArrowUp', ' '].includes(e.code || e.key)) keys.fire = false;
});
let isPointerDown = false;
canvas.addEventListener('pointerdown', (e) => {
if (!isRunning) return;
isPointerDown = true;
const rect = canvas.getBoundingClientRect();
const clickX = ((e.clientX - rect.left) / rect.width) * canvas.width;
player.x = Math.max(player.width / 2, Math.min(canvas.width - player.width / 2, clickX));
keys.fire = true;
});
canvas.addEventListener('pointermove', (e) => {
if (!isRunning || !isPointerDown) return;
const rect = canvas.getBoundingClientRect();
const clickX = ((e.clientX - rect.left) / rect.width) * canvas.width;
player.x = Math.max(player.width / 2, Math.min(canvas.width - player.width / 2, clickX));
});
window.addEventListener('pointerup', () => {
isPointerDown = false;
keys.fire = false;
});
if (touchBtnLeft) {
touchBtnLeft.addEventListener('touchstart', (e) => { e.preventDefault(); keys.left = true; });
touchBtnLeft.addEventListener('touchend', (e) => { e.preventDefault(); keys.left = false; });
touchBtnLeft.addEventListener('mousedown', () => { keys.left = true; });
touchBtnLeft.addEventListener('mouseup', () => { keys.left = false; });
}
if (touchBtnRight) {
touchBtnRight.addEventListener('touchstart', (e) => { e.preventDefault(); keys.right = true; });
touchBtnRight.addEventListener('touchend', (e) => { e.preventDefault(); keys.right = false; });
touchBtnRight.addEventListener('mousedown', () => { keys.right = true; });
touchBtnRight.addEventListener('mouseup', () => { keys.right = false; });
}
if (touchBtnFire) {
touchBtnFire.addEventListener('touchstart', (e) => { e.preventDefault(); keys.fire = true; });
touchBtnFire.addEventListener('touchend', (e) => { e.preventDefault(); keys.fire = false; });
touchBtnFire.addEventListener('mousedown', () => { keys.fire = true; });
touchBtnFire.addEventListener('mouseup', () => { keys.fire = false; });
}
const BUG_TYPES = [
{ name: 'SyntaxError', icon: '🐞', hp: 1, speed: 110, score: 20, color: '#ef4444', size: 26 },
{ name: 'NullPointer', icon: '🕷️', hp: 2, speed: 140, score: 40, color: '#8b5cf6', size: 30 },
{ name: '404Exception', icon: '⚠️', hp: 3, speed: 90, score: 60, color: '#f59e0b', size: 32 },
{ name: 'MemoryLeak', icon: '💣', hp: 5, speed: 65, score: 120, color: '#06b6d4', size: 36 }
];
const POWERUP_TYPES = [
{ type: 'rapid', label: 'PHP RAPID', color: '#8892bf', icon: '🐘' },
{ type: 'shield', label: 'LARAVEL SHIELD', color: '#ff2d20', icon: '🔴' },
{ type: 'spread', label: 'KOTLIN 3-WAY', color: '#7f52ff', icon: '🔷' },
{ type: 'bonus', label: 'COMTEQ +150', color: '#38bdf8', icon: '💎' }
];
const spawnBug = () => {
const typeIndex = Math.min(
BUG_TYPES.length - 1,
Math.floor(Math.random() * (1 + wave * 0.5))
);
const proto = BUG_TYPES[typeIndex];
const x = Math.random() * (canvas.width - proto.size * 2) + proto.size;
bugs.push({
x: x,
y: -30,
name: proto.name,
icon: proto.icon,
hp: proto.hp + Math.floor(wave / 3),
maxHp: proto.hp + Math.floor(wave / 3),
speed: proto.speed + wave * 8,
score: proto.score * wave,
color: proto.color,
size: proto.size,
wobble: Math.random() * Math.PI * 2,
wobbleSpeed: Math.random() * 3 + 1
});
};
const spawnPowerup = () => {
const proto = POWERUP_TYPES[Math.floor(Math.random() * POWERUP_TYPES.length)];
const x = Math.random() * (canvas.width - 60) + 30;
powerups.push({
x: x,
y: -25,
type: proto.type,
label: proto.label,
color: proto.color,
icon: proto.icon,
size: 22,
speed: 90
});
};
const addExplosion = (x, y, color, count = 16) => {
for (let i = 0; i < count; i++) {
const angle = Math.random() * Math.PI * 2;
const speed = Math.random() * 180 + 30;
particles.push({
x: x,
y: y,
vx: Math.cos(angle) * speed,
vy: Math.sin(angle) * speed,
radius: Math.random() * 3.5 + 1.5,
color: color,
life: 1,
decay: Math.random() * 1.5 + 1.2
});
}
};
const fireLaser = () => {
sound.playLaser();
if (player.spreadShot) {
lasers.push({ x: player.x, y: player.y - 14, vx: 0, vy: -550 });
lasers.push({ x: player.x - 12, y: player.y - 10, vx: -120, vy: -520 });
lasers.push({ x: player.x + 12, y: player.y - 10, vx: 120, vy: -520 });
} else {
lasers.push({ x: player.x - 9, y: player.y - 12, vx: 0, vy: -560 });
lasers.push({ x: player.x + 9, y: player.y - 12, vx: 0, vy: -560 });
}
};
const resetGame = () => {
score = 0;
bugsSquashed = 0;
wave = 1;
player.x = canvas.width / 2;
player.shield = 100;
player.spreadShot = false;
player.rapidFire = false;
lasers = [];
bugs = [];
powerups = [];
particles = [];
bugSpawnTimer = 0;
powerupSpawnTimer = 0;
if (gameScoreVal) gameScoreVal.textContent = '00000';
if (gameShieldBar) gameShieldBar.style.width = '100%';
};
const startGame = () => {
sound.playSuccess();
resetGame();
isRunning = true;
if (overlayStart) overlayStart.classList.add('hidden');
if (overlayGameOver) overlayGameOver.classList.add('hidden');
lastTime = performance.now();
if (animationId) cancelAnimationFrame(animationId);
animationId = requestAnimationFrame(gameLoop);
};
const triggerGameOver = () => {
isRunning = false;
sound.playExplosion();
if (score > highScore) {
highScore = score;
localStorage.setItem('al_dev_highscore', highScore.toString());
if (gameHighVal) gameHighVal.textContent = String(highScore).padStart(5, '0');
}
if (goScoreText) goScoreText.textContent = score;
if (goBugsText) goBugsText.textContent = bugsSquashed;
if (goWaveText) goWaveText.textContent = wave;
if (goRecordText) goRecordText.textContent = highScore;
if (overlayGameOver) overlayGameOver.classList.remove('hidden');
};
if (btnStartGameAction) btnStartGameAction.addEventListener('click', startGame);
if (btnRestartGameAction) btnRestartGameAction.addEventListener('click', startGame);
const gameLoop = (currentTime) => {
if (!isRunning) return;
const dt = Math.min((currentTime - lastTime) / 1000, 0.1);
lastTime = currentTime;
let moveDir = 0;
if (keys.left) moveDir -= 1;
if (keys.right) moveDir += 1;
player.x += moveDir * player.speed * dt;
player.x = Math.max(player.width / 2, Math.min(canvas.width - player.width / 2, player.x));
player.fireTimer -= dt;
const currentFireInterval = player.rapidFire ? 0.09 : 0.18;
if (keys.fire && player.fireTimer <= 0) {
fireLaser();
player.fireTimer = currentFireInterval;
}
if (player.spreadShot) {
player.spreadTimer -= dt;
if (player.spreadTimer <= 0) player.spreadShot = false;
}
if (player.rapidFire) {
player.rapidTimer -= dt;
if (player.rapidTimer <= 0) player.rapidFire = false;
}
stars.forEach((star) => {
star.y += star.speed * dt;
if (star.y > canvas.height) {
star.y = 0;
star.x = Math.random() * canvas.width;
}
});
bugSpawnTimer += dt;
const spawnInterval = Math.max(0.45, 1.4 - wave * 0.12);
if (bugSpawnTimer >= spawnInterval) {
spawnBug();
bugSpawnTimer = 0;
}
powerupSpawnTimer += dt;
if (powerupSpawnTimer >= 8.5) {
spawnPowerup();
powerupSpawnTimer = 0;
}
for (let i = lasers.length - 1; i >= 0; i--) {
const l = lasers[i];
l.x += l.vx * dt;
l.y += l.vy * dt;
if (l.y < -10 || l.x < 0 || l.x > canvas.width) {
lasers.splice(i, 1);
}
}
for (let i = bugs.length - 1; i >= 0; i--) {
const b = bugs[i];
b.wobble += b.wobbleSpeed * dt;
b.x += Math.sin(b.wobble) * 35 * dt;
b.y += b.speed * dt;
if (b.y > canvas.height - 25) {
bugs.splice(i, 1);
player.shield -= 15;
sound.playHit();
addExplosion(b.x, canvas.height - 20, '#ef4444', 12);
if (gameShieldBar) {
gameShieldBar.style.width = `${Math.max(0, player.shield)}%`;
}
if (player.shield <= 0) {
triggerGameOver();
return;
}
continue;
}
for (let j = lasers.length - 1; j >= 0; j--) {
const l = lasers[j];
const dist = Math.hypot(l.x - b.x, l.y - b.y);
if (dist < b.size * 0.85) {
lasers.splice(j, 1);
b.hp -= 1;
addExplosion(l.x, l.y, '#38bdf8', 4);
if (b.hp <= 0) {
sound.playExplosion();
addExplosion(b.x, b.y, b.color, 18);
score += b.score;
bugsSquashed += 1;
if (gameScoreVal) {
gameScoreVal.textContent = String(score).padStart(5, '0');
}
if (bugsSquashed % 10 === 0) {
wave += 1;
sound.playPowerup();
}
bugs.splice(i, 1);
}
break;
}
}
}
for (let i = powerups.length - 1; i >= 0; i--) {
const p = powerups[i];
p.y += p.speed * dt;
const dist = Math.hypot(p.x - player.x, p.y - player.y);
if (dist < player.width * 0.75 + p.size) {
sound.playPowerup();
addExplosion(p.x, p.y, p.color, 14);
if (p.type === 'rapid') {
player.rapidFire = true;
player.rapidTimer = 8;
} else if (p.type === 'shield') {
player.shield = Math.min(100, player.shield + 35);
if (gameShieldBar) gameShieldBar.style.width = `${player.shield}%`;
} else if (p.type === 'spread') {
player.spreadShot = true;
player.spreadTimer = 8;
} else if (p.type === 'bonus') {
score += 150;
if (gameScoreVal) gameScoreVal.textContent = String(score).padStart(5, '0');
}
powerups.splice(i, 1);
continue;
}
if (p.y > canvas.height + 20) {
powerups.splice(i, 1);
}
}
for (let i = particles.length - 1; i >= 0; i--) {
const pt = particles[i];
pt.x += pt.vx * dt;
pt.y += pt.vy * dt;
pt.life -= pt.decay * dt;
if (pt.life <= 0) {
particles.splice(i, 1);
}
}
ctx.fillStyle = '#06080e';
ctx.fillRect(0, 0, canvas.width, canvas.height);
ctx.strokeStyle = 'rgba(56, 189, 248, 0.04)';
ctx.lineWidth = 1;
for (let gx = 0; gx < canvas.width; gx += 40) {
ctx.beginPath();
ctx.moveTo(gx, 0);
ctx.lineTo(gx, canvas.height);
ctx.stroke();
}
for (let gy = 0; gy < canvas.height; gy += 40) {
ctx.beginPath();
ctx.moveTo(0, gy);
ctx.lineTo(canvas.width, gy);
ctx.stroke();
}
stars.forEach((star) => {
ctx.fillStyle = `rgba(186, 230, 253, ${star.alpha})`;
ctx.fillRect(star.x, star.y, star.size, star.size);
});
ctx.strokeStyle = player.shield > 25 ? 'rgba(56, 189, 248, 0.3)' : 'rgba(239, 68, 68, 0.5)';
ctx.setLineDash([4, 4]);
ctx.beginPath();
ctx.moveTo(0, canvas.height - 25);
ctx.lineTo(canvas.width, canvas.height - 25);
ctx.stroke();
ctx.setLineDash([]);
lasers.forEach((l) => {
ctx.fillStyle = '#38bdf8';
ctx.shadowColor = '#0284c7';
ctx.shadowBlur = 8;
ctx.fillRect(l.x - 2, l.y - 12, 4, 14);
ctx.shadowBlur = 0;
});
bugs.forEach((b) => {
ctx.save();
ctx.translate(b.x, b.y);
ctx.shadowColor = b.color;
ctx.shadowBlur = 10;
ctx.fillStyle = b.color;
ctx.beginPath();
ctx.arc(0, 0, b.size * 0.45, 0, Math.PI * 2);
ctx.fill();
ctx.shadowBlur = 0;
ctx.font = `${b.size}px monospace`;
ctx.textAlign = 'center';
ctx.textBaseline = 'middle';
ctx.fillText(b.icon, 0, 0);
if (b.maxHp > 1) {
const barW = 26;
const barH = 3;
ctx.fillStyle = 'rgba(0, 0, 0, 0.6)';
ctx.fillRect(-barW / 2, -b.size * 0.8, barW, barH);
ctx.fillStyle = b.color;
ctx.fillRect(-barW / 2, -b.size * 0.8, (b.hp / b.maxHp) * barW, barH);
}
ctx.restore();
});
powerups.forEach((p) => {
ctx.save();
ctx.translate(p.x, p.y);
ctx.shadowColor = p.color;
ctx.shadowBlur = 12;
ctx.fillStyle = 'rgba(15, 23, 42, 0.85)';
ctx.strokeStyle = p.color;
ctx.lineWidth = 1.5;
ctx.beginPath();
ctx.arc(0, 0, p.size, 0, Math.PI * 2);
ctx.fill();
ctx.stroke();
ctx.font = '16px monospace';
ctx.textAlign = 'center';
ctx.textBaseline = 'middle';
ctx.fillText(p.icon, 0, 0);
ctx.font = '9px "JetBrains Mono", monospace';
ctx.fillStyle = p.color;
ctx.fillText(p.label, 0, p.size + 9);
ctx.restore();
});
particles.forEach((pt) => {
ctx.fillStyle = pt.color;
ctx.globalAlpha = Math.max(0, pt.life);
ctx.beginPath();
ctx.arc(pt.x, pt.y, pt.radius, 0, Math.PI * 2);
ctx.fill();
});
ctx.globalAlpha = 1;
ctx.save();
ctx.translate(player.x, player.y);
ctx.fillStyle = '#38bdf8';
ctx.beginPath();
ctx.moveTo(-6, player.height / 2);
ctx.lineTo(0, player.height / 2 + Math.random() * 10 + 6);
ctx.lineTo(6, player.height / 2);
ctx.closePath();
ctx.fill();
ctx.shadowColor = '#38bdf8';
ctx.shadowBlur = 12;
ctx.fillStyle = '#0f172a';
ctx.strokeStyle = '#38bdf8';
ctx.lineWidth = 2;
ctx.beginPath();
ctx.moveTo(0, -player.height / 2);
ctx.lineTo(player.width / 2, player.height / 2);
ctx.lineTo(0, player.height / 2 - 6);
ctx.lineTo(-player.width / 2, player.height / 2);
ctx.closePath();
ctx.fill();
ctx.stroke();
ctx.fillStyle = '#38bdf8';
ctx.beginPath();
ctx.arc(0, -2, 4, 0, Math.PI * 2);
ctx.fill();
if (player.spreadShot || player.rapidFire) {
ctx.strokeStyle = player.rapidFire ? '#8892bf' : '#7f52ff';
ctx.lineWidth = 1.5;
ctx.beginPath();
ctx.arc(0, 0, player.width * 0.75, 0, Math.PI * 2);
ctx.stroke();
}
ctx.restore();
ctx.font = '10px "JetBrains Mono", monospace';
ctx.fillStyle = 'rgba(148, 163, 184, 0.7)';
ctx.textAlign = 'left';
ctx.fillText(`WAVE: ${wave}  •  SQUASHED: ${bugsSquashed}`, 14, 20);
animationId = requestAnimationFrame(gameLoop);
};
}
const tabGameShooter = document.getElementById('tabGameShooter');
const tabGameMatrix = document.getElementById('tabGameMatrix');
const viewShooter = document.getElementById('viewShooter');
const viewMatrix = document.getElementById('viewMatrix');
const mobileGamepad = document.getElementById('mobileGamepad');
if (tabGameShooter && tabGameMatrix && viewShooter && viewMatrix) {
tabGameShooter.addEventListener('click', () => {
sound.playClick();
tabGameShooter.classList.add('active');
tabGameMatrix.classList.remove('active');
viewShooter.classList.add('active');
viewShooter.classList.remove('hidden');
viewMatrix.classList.remove('active');
viewMatrix.classList.add('hidden');
if (mobileGamepad) mobileGamepad.style.display = 'flex';
});
tabGameMatrix.addEventListener('click', () => {
sound.playClick();
tabGameMatrix.classList.add('active');
tabGameShooter.classList.remove('active');
viewMatrix.classList.add('active');
viewMatrix.classList.remove('hidden');
viewShooter.classList.remove('active');
viewShooter.classList.add('hidden');
if (mobileGamepad) mobileGamepad.style.display = 'none';
});
}
const matrixTargetWord = document.getElementById('matrixTargetWord');
const matrixTimerFill = document.getElementById('matrixTimerFill');
const matrixOptionsGrid = document.getElementById('matrixOptionsGrid');
const matrixStreakVal = document.getElementById('matrixStreakVal');
const matrixScoreVal = document.getElementById('matrixScoreVal');
const btnMatrixStart = document.getElementById('btnMatrixStart');
const CODE_MODULES = [
{ target: 'LARAVEL_MIGRATION', prompt: 'php artisan make:migration', options: ['php artisan make:migration', 'composer update db', 'npm run migrate', 'flask db init'] },
{ target: 'JETPACK_COMPOSE', prompt: '@Composable fun MainScreen()', options: ['@Composable fun MainScreen()', 'function render()', 'class ViewWidget', 'def build()'] },
{ target: 'PHP_NULLSAFE', prompt: '$user?->company?->name', options: ['$user?->company?->name', '$user.company.name', '$user->get("name")', '$user["company"]["name"]'] },
{ target: 'ROOM_DATABASE', prompt: '@Dao interface NoteDao', options: ['@Dao interface NoteDao', '@Repository class Note', '@Entity struct Note', '@Schema db Note'] },
{ target: 'ELOQUENT_ORM', prompt: 'User::with("orders")->get()', options: ['User::with("orders")->get()', 'SELECT * FROM users', 'User.find().populate()', 'db.users.aggregate()'] },
{ target: 'KOTLIN_FLOW', prompt: 'viewModelScope.launch { flow.collect() }', options: ['viewModelScope.launch { flow.collect() }', 'async function fetch()', 'Thread.start(runnable)', 'Rx.Observable.from()'] },
{ target: 'TAILWIND_CLASS', prompt: 'grid grid-cols-1 md:grid-cols-3 gap-6', options: ['grid grid-cols-1 md:grid-cols-3 gap-6', 'display: grid; flex: 1;', 'float: left; width: 33%;', '.col-md-4 { margin: 10px }'] },
{ target: 'DOMPDF_STREAM', prompt: 'Pdf::loadView("invoice", $data)->stream()', options: ['Pdf::loadView("invoice", $data)->stream()', 'window.print("invoice.pdf")', 'PDF.createStream(file)', 'document.exportPDF()'] }
];
let matrixStreak = 0;
let matrixScore = 0;
let matrixTimer = null;
let matrixTimeLeft = 100;
const runMatrixRound = () => {
if (!matrixTargetWord || !matrixOptionsGrid || !matrixTimerFill) return;
const round = CODE_MODULES[Math.floor(Math.random() * CODE_MODULES.length)];
matrixTargetWord.textContent = `${round.target} ❯ ${round.prompt}`;
const shuffled = [...round.options].sort(() => Math.random() - 0.5);
matrixOptionsGrid.innerHTML = '';
shuffled.forEach((opt) => {
const btn = document.createElement('button');
btn.className = 'matrix-opt-btn';
btn.textContent = opt;
btn.addEventListener('click', () => {
if (opt === round.prompt) {
sound.playSuccess();
matrixStreak += 1;
matrixScore += 100 * matrixStreak;
if (matrixStreakVal) matrixStreakVal.textContent = matrixStreak;
if (matrixScoreVal) matrixScoreVal.textContent = matrixScore;
btn.style.borderColor = '#10b981';
btn.style.color = '#10b981';
clearInterval(matrixTimer);
setTimeout(runMatrixRound, 400);
} else {
sound.playHit();
matrixStreak = 0;
if (matrixStreakVal) matrixStreakVal.textContent = '0';
btn.style.borderColor = '#ef4444';
btn.style.color = '#ef4444';
}
});
matrixOptionsGrid.appendChild(btn);
});
clearInterval(matrixTimer);
matrixTimeLeft = 100;
matrixTimerFill.style.width = '100%';
matrixTimer = setInterval(() => {
matrixTimeLeft -= 1.6;
matrixTimerFill.style.width = `${Math.max(0, matrixTimeLeft)}%`;
if (matrixTimeLeft <= 0) {
clearInterval(matrixTimer);
sound.playHit();
matrixStreak = 0;
if (matrixStreakVal) matrixStreakVal.textContent = '0';
runMatrixRound();
}
}, 100);
};
if (btnMatrixStart) {
btnMatrixStart.addEventListener('click', () => {
sound.playPowerup();
matrixStreak = 0;
matrixScore = 0;
if (matrixStreakVal) matrixStreakVal.textContent = '0';
if (matrixScoreVal) matrixScoreVal.textContent = '0';
btnMatrixStart.textContent = 'Reset Session';
runMatrixRound();
});
}
if (matrixOptionsGrid) {
CODE_MODULES[0].options.forEach((opt) => {
const btn = document.createElement('button');
btn.className = 'matrix-opt-btn';
btn.textContent = opt;
matrixOptionsGrid.appendChild(btn);
});
}
